    l--;
    r++;
  }
  return r - l - 1;
}

let best = len > 0 ? 1 : 0;
for (let i = 0; i < len; i++) {
  const odd = expand(i, i);       // palíndromo de comprimento ímpar centrado em i
  const even = expand(i, i + 1);  // palíndromo de comprimento par centrado entre i e i+1
